package com.primehr.operations;
import com.primehr.evidence.application.*;import com.primehr.evidence.domain.EvidenceArtifact;import com.primehr.evidence.infrastructure.EvidenceArtifactRepository;import com.primehr.operations.application.OperationsObservability;import com.primehr.operations.application.OperationsServiceImpl;import com.primehr.operations.domain.*;import com.primehr.operations.infrastructure.*;import com.primehr.rsp.applicant.storage.DocumentStorage;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class OperationsServiceImplTest {ReconciliationRunRepository runs=mock(ReconciliationRunRepository.class);ReconciliationFindingRepository findings=mock(ReconciliationFindingRepository.class);RetentionPolicyVersionRepository policies=mock(RetentionPolicyVersionRepository.class);LegalHoldRepository holds=mock(LegalHoldRepository.class);EvidenceArtifactRepository artifacts=mock(EvidenceArtifactRepository.class);StoredDocumentCatalog documents=mock(StoredDocumentCatalog.class);EvidenceLiveSourceVerifier verifier=mock(EvidenceLiveSourceVerifier.class);DocumentStorage storage=mock(DocumentStorage.class);PrimeHrAuditService audit=mock(PrimeHrAuditService.class);OperationsObservability observability=mock(OperationsObservability.class);OperationsServiceImpl service;
 @BeforeEach void setUp(){service=new OperationsServiceImpl(runs,findings,policies,holds,artifacts,documents,verifier,storage,audit,observability);when(documents.documents(anyString())).thenReturn(List.of());when(documents.retentionRecords(anyString())).thenReturn(List.of());when(runs.saveAndFlush(any())).thenAnswer(i->{var r=(ReconciliationRun)i.getArgument(0);if(r.getId()==null)ReflectionTestUtils.setField(r,"id","run");return r;});when(findings.findByAgencyIdAndRunIdOrderByCreatedAtAsc(anyString(),anyString())).thenReturn(List.of());}
 @Test void recordsDriftWithoutChangingHistoricalArtifact(){var a=live();when(artifacts.findByAgencyIdOrderByAddedAtAsc("A")).thenReturn(List.of(a));when(verifier.verify(anyString(),any(),anyString(),anyString(),isNull())).thenThrow(new OptimisticConflictException("changed"));service.run("A","Bearer token","operator",null,false);var capture=ArgumentCaptor.forClass(ReconciliationFinding.class);verify(findings).save(capture.capture());assertThat(capture.getValue().getKind()).isEqualTo(ReconciliationFinding.Kind.SOURCE_DRIFT);verify(artifacts,never()).save(any());}
 @Test void distinguishesMissingAuthoritativeSource(){var a=live();when(artifacts.findByAgencyIdOrderByAddedAtAsc("A")).thenReturn(List.of(a));when(verifier.verify(anyString(),any(),anyString(),anyString(),isNull())).thenThrow(new ResourceNotFoundException("missing"));service.run("A","Bearer token","operator",null,false);var capture=ArgumentCaptor.forClass(ReconciliationFinding.class);verify(findings).save(capture.capture());assertThat(capture.getValue().getKind()).isEqualTo(ReconciliationFinding.Kind.SOURCE_MISSING);}
 @Test void storageCheckUsesMetadataAndNeverReadsContent(){when(documents.documents("A")).thenReturn(List.of(new StoredDocumentCatalog.DocumentReference("EVIDENCE_ARTIFACT","upload","A/evidence/upload",10L)));when(storage.metadata("A/evidence/upload")).thenReturn(new DocumentStorage.StorageObjectMetadata(false,null,null));service.run("A","Bearer token","operator",null,false);var capture=ArgumentCaptor.forClass(ReconciliationFinding.class);verify(findings).save(capture.capture());assertThat(capture.getValue().getKind()).isEqualTo(ReconciliationFinding.Kind.STORAGE_MISSING);verify(storage,never()).get(anyString());}
 @Test void activeLegalHoldBlocksOtherwiseEligibleRetentionRecord(){when(documents.retentionRecords("A")).thenReturn(List.of(new StoredDocumentCatalog.RetentionReference("EVIDENCE_ARTIFACT","upload","CASE",LocalDate.of(2020,1,1))));when(policies.findByAgencyIdOrderByCodeAscPolicyVersionDesc("A")).thenReturn(List.of(new RetentionPolicyVersion("A","CASE",1,"CASE",365,LocalDate.of(2019,1,1),null,"policy",true)));when(holds.existsByAgencyIdAndRecordTypeAndRecordIdAndActiveTrue("A","EVIDENCE_ARTIFACT","upload")).thenReturn(true);var report=service.retentionReport("A",LocalDate.of(2026,1,1));assertThat(report).singleElement().satisfies(x->{assertThat(x.legalHold()).isTrue();assertThat(x.eligible()).isFalse();});}
 private EvidenceArtifact live(){var a=mock(EvidenceArtifact.class);when(a.getKind()).thenReturn(EvidenceArtifact.Kind.LIVE_SOURCE);when(a.getId()).thenReturn("artifact");when(a.getSourceType()).thenReturn(EvidenceArtifact.SourceType.PERFORMANCE_OUTCOME);when(a.getSourceId()).thenReturn("source");when(a.getSourceVersion()).thenReturn(1L);when(a.getSourceFingerprint()).thenReturn("0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef");when(a.getSourceChangedAt()).thenReturn(Instant.parse("2026-01-01T00:00:00Z"));return a;}
}
